query:
query Issues($filter: IssueFilter, $after: String) { issues(filter: $filter, first: 100, after: $after) {
    nodes { id number title description state { type } creator { id } createdAt labels { nodes { id name updatedAt } }
  comments(first: 250) { nodes { id body createdAt user { id } } } } pageInfo { hasNextPage endCursor } } }
